import{_ as e,o,c as d,a3 as a}from"./chunks/framework.CRbjHCyB.js";const b=JSON.parse('{"title":"Configuration","description":"","frontmatter":{"outline":2,"head":[["meta",{"property":"og:title","content":"Configuration | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/guide/configuration"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/guide/configuration"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/configuration"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/configuration"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/configuration"}]]},"headers":[],"relativePath":"clice/guide/configuration.md","filePath":"en/clice/guide/configuration.md","lastUpdated":1788674121000}'),i={name:"clice/guide/configuration.md"};function n(s,t,c,r,l,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>clice reads configuration from <code>clice.toml</code> in the workspace root, or from <code>.clice/config.toml</code> if the former does not exist. Configuration can also be passed via LSP <code>initializationOptions</code> (JSON format); values from <code>initializationOptions</code> override the config file, and defaults fill in whatever remains unset after the merge.</p><p>Configuration is read once at server startup. Changing it — either file — requires restarting the server; there is no hot reload.</p><p>A JSON schema of the whole configuration is published at <a href="/clice-config.schema.json"><code>clice-config.schema.json</code></a>; editors that validate TOML or JSON against a schema can point at it.</p><h2 id="variable-substitution" tabindex="-1">Variable Substitution <a class="header-anchor" href="#variable-substitution" aria-label="Permalink to &quot;Variable Substitution&quot;">​</a></h2><p>The following variable is supported in string values:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${workspace}</code></td><td>The workspace directory provided by the client</td></tr></tbody></table><h2 id="project" tabindex="-1"><code>[project]</code> <a class="header-anchor" href="#project" aria-label="Permalink to &quot;`[project]`&quot;">​</a></h2><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>cache_dir</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>Directory for the unified on-disk cache (PCH, PCM and index artifacts). Empty defaults to <code>${workspace}/.clice</code>, which keeps itself out of version control and backups via generated .gitignore and CACHEDIR.TAG markers (a <code>.clice/config.toml</code> stays visible to Git; backup tools honoring CACHEDIR.TAG skip the whole directory); an explicitly configured directory is never marked. The resolved path is printed at startup.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>logging_dir</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>Directory for log files; empty derives <code>${cache_dir}/logs</code>. Each server session logs into its own timestamped subdirectory.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>compile_commands_paths</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Paths searched for compile_commands.json — file paths, or directories to look inside. When these all miss — or the list is empty — the workspace root and then each of its immediate subdirectories are searched.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>enable_indexing</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Build the background index that serves cross-TU features (find references, workspace symbols, ...).</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>readonly</code></td><td><code>string</code></td><td><code>&quot;off&quot;</code></td></tr></tbody></table><p>Read-only serving for open files: &quot;off&quot; targets a full AST for every open file — builds are pulled by the first request that needs them, with the index answering in the meantime; &quot;on&quot; never builds a PCH — reads serve from the index alone (a cold file jumps the indexing queue), while completion and signature help still compile on demand without a preamble; &quot;auto&quot; starts every file as &quot;on&quot;, switches it to &quot;off&quot; at the first edit intent (edit, completion, signature help, context switch), and falls back to &quot;off&quot; for a file the index cannot serve. Feature routing always answers from the best source currently available.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>idle_timeout_ms</code></td><td><code>uint32</code></td><td><code>3000</code></td></tr></tbody></table><p>Idle delay in milliseconds before background indexing starts.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>test_hooks</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Enable the clice/internal test hooks used by the test harness.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>stateful_worker_count</code></td><td><code>uint32</code></td><td><code>2</code></td></tr></tbody></table><p>Number of stateful workers — they hold ASTs in memory and serve queries (hover, semantic tokens, ...); <code>0</code> is invalid and falls back to the default.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>stateless_worker_count</code></td><td><code>uint32</code></td><td>—</td></tr></tbody></table><p>Initial number of stateless workers — they handle ephemeral tasks (PCH/PCM builds, completion, signature help); defaults to half the machine&#39;s parallelism, at least 2. <code>0</code> is invalid and falls back to that default.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>min_stateless_worker_count</code></td><td><code>uint32</code></td><td><code>1</code></td></tr></tbody></table><p>Lower bound for dynamic stateless-worker scaling; <code>0</code> is invalid and falls back to the default.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>max_stateless_worker_count</code></td><td><code>uint32</code></td><td>—</td></tr></tbody></table><p>Upper bound for dynamic stateless-worker scaling; <code>0</code> means the machine&#39;s parallelism, which is also the default.</p></div><h2 id="tracker" tabindex="-1"><code>[tracker]</code> <a class="header-anchor" href="#tracker" aria-label="Permalink to &quot;`[tracker]`&quot;">​</a></h2><p>The file tracker polls for changes that happen outside the editor (a <code>git checkout</code>, a regenerated <code>compile_commands.json</code>, code generators writing headers) so the server picks them up without a restart. Setting an interval to <code>0</code> disables that polling loop.</p><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>cdb_poll_seconds</code></td><td><code>uint32</code></td><td><code>3</code></td></tr></tbody></table><p>Compilation database poll interval in seconds; 0 disables polling.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>workspace_poll_seconds</code></td><td><code>uint32</code></td><td><code>30</code></td></tr></tbody></table><p>Workspace file sweep interval in seconds; 0 disables polling.</p></div><h2 id="hover" tabindex="-1"><code>[hover]</code> <a class="header-anchor" href="#hover" aria-label="Permalink to &quot;`[hover]`&quot;">​</a></h2><p>The <code>[hover]</code> section controls how hover cards render.</p><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>parse_comment_as_markdown</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Render the hover card as markdown; <code>false</code> produces plain text for clients that cannot display it.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>show_aka</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Show the desugared form of a type, e.g. <code>vector&lt;int&gt;::size_type (aka unsigned long)</code>.</p></div><h2 id="inlay-hints" tabindex="-1"><code>[inlay_hints]</code> <a class="header-anchor" href="#inlay-hints" aria-label="Permalink to &quot;`[inlay_hints]`&quot;">​</a></h2><p>The <code>[inlay_hints]</code> section controls which inlay hint categories the server produces. A client-side refresh then requests hints with the updated values; no recompile is involved.</p><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Master switch: <code>false</code> disables all inlay hints.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>parameters</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Parameter name hints at call sites, e.g. <code>draw(width: 800, height: 600)</code>, including <code>&amp;</code> markers for arguments passed by mutable reference.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>deduced_types</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Deduced type hints for <code>auto</code> variables, structured bindings and deduced return types.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>designators</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Field designator hints in aggregate initialization, e.g. <code>.x=</code> and <code>.y=</code> in <code>Point{1, 2}</code>.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>block_end</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p><code>// name</code> hints after the closing brace of long blocks (functions, types, namespaces, control flow).</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>default_arguments</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Show the default arguments a call omitted, abbreviated when long.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>type_name_limit</code></td><td><code>uint32</code></td><td><code>32</code></td></tr></tbody></table><p>Byte budget for rendered hint text: over-long deduced types fall back to a sugared spelling or are dropped, over-long default arguments are abbreviated. <code>0</code> means no limit.</p></div><h2 id="code-completion" tabindex="-1"><code>[code_completion]</code> <a class="header-anchor" href="#code-completion" aria-label="Permalink to &quot;`[code_completion]`&quot;">​</a></h2><p>The <code>[code_completion]</code> section controls completion item assembly.</p><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>enable_keyword_snippet</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Complete keywords as snippets (not yet implemented).</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>enable_function_arguments_snippet</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Insert function arguments as a snippet when completing a call. For functions this applies to individually listed overloads, so it requires <code>bundle_overloads = false</code>; function-like macros have no overload sets and always take the snippet.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>enable_template_arguments_snippet</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Insert template arguments as a snippet on completion (not yet implemented).</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>insert_paren_in_function_call</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Insert parentheses when completing a function call (not yet implemented).</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bundle_overloads</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Collapse an overload set into a single completion item.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>uint32</code></td><td><code>0</code></td></tr></tbody></table><p>Maximum number of completion items (not yet implemented).</p></div><h2 id="rules" tabindex="-1"><code>[[rules]]</code> <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;`[[rules]]`&quot;">​</a></h2><p><code>[[rules]]</code> is an array of rule objects. Rules are matched in declaration order — later rules override earlier ones.</p><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>patterns</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Glob patterns selecting the files this rule applies to: <code>*</code> matches within a path segment (a pattern of just <code>*</code> matches any path), <code>?</code> a single character, <code>**</code> any number of segments, <code>{a,b}</code> alternatives, <code>[0-9]</code> a character range, <code>[!...]</code> a negated range.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>append</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Compilation flags appended for matching files, e.g. <code>[&quot;-std=c++20&quot;, &quot;-DNDEBUG&quot;]</code>.</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>remove</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Compilation flags removed for matching files, e.g. <code>[&quot;-Wall&quot;]</code>.</p></div><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">compile_commands_paths = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${workspace}/build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${workspace}/cmake-build-debug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">append = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-std=c++23&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/test/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">append = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-DTEST_MODE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div>',51)])])}const u=e(i,[["render",n]]);export{b as __pageData,u as default};
